import { promises as fs } from "fs";
import path from "path";
import { dataPath, readJson, writeJson } from "./store/jsonStore";
import { getConfig } from "./config";

interface CacheEnvelope<T> {
  fetchedAt: string;
  source: string;
  payload: T;
}

export async function getCached<T>(key: string): Promise<CacheEnvelope<T> | null> {
  return readJson<CacheEnvelope<T>>(`cache/${key}.json`);
}

export async function setCached<T>(
  key: string,
  source: string,
  payload: T,
): Promise<CacheEnvelope<T>> {
  const envelope: CacheEnvelope<T> = {
    fetchedAt: new Date().toISOString(),
    source,
    payload,
  };
  await writeJson(`cache/${key}.json`, envelope);
  return envelope;
}

export function isFresh(fetchedAt: string, ttlMinutes: number): boolean {
  const age = Date.now() - new Date(fetchedAt).getTime();
  return age < ttlMinutes * 60_000;
}

export async function cachedFetch<T>(opts: {
  key: string;
  source: string;
  ttlMinutes?: number;
  loader: () => Promise<T>;
}): Promise<{ data: T; fetchedAt: string; fromCache: boolean; stale: boolean; source: string }> {
  const cfg = await getConfig();
  const ttl = opts.ttlMinutes ?? cfg.cacheTtlMinutes;
  const existing = await getCached<T>(opts.key);

  if (existing && isFresh(existing.fetchedAt, ttl)) {
    return {
      data: existing.payload,
      fetchedAt: existing.fetchedAt,
      fromCache: true,
      stale: false,
      source: existing.source,
    };
  }

  try {
    const payload = await opts.loader();
    const saved = await setCached(opts.key, opts.source, payload);
    return {
      data: payload,
      fetchedAt: saved.fetchedAt,
      fromCache: false,
      stale: false,
      source: opts.source,
    };
  } catch (err) {
    if (existing) {
      return {
        data: existing.payload,
        fetchedAt: existing.fetchedAt,
        fromCache: true,
        stale: true,
        source: existing.source,
      };
    }
    throw err;
  }
}

export async function clearWeatherCache(): Promise<number> {
  const dir = dataPath("cache");
  try {
    const files = await fs.readdir(dir);
    await Promise.all(files.map((f) => fs.unlink(path.join(dir, f))));
    return files.length;
  } catch {
    return 0;
  }
}

import type { AppConfig } from "./types";
import { readJson, writeJson } from "./store/jsonStore";

export const DEFAULT_CONFIG: AppConfig = {
  weights: {
    water: 0.3,
    pressure: 0.2,
    wind: 0.2,
    cloud: 0.15,
    historical: 0.15,
  },
  levels: {
    tresMauvais: 0,
    faible: 21,
    moyen: 41,
    bon: 61,
    tresBon: 76,
    exceptionnel: 91,
  },
  cacheTtlMinutes: 20,
  sectorId: "sanguinet",
  anglerName: "",
  notifications: false,
};

export async function getConfig(): Promise<AppConfig> {
  const stored = await readJson<AppConfig>("config.json");
  if (!stored) return DEFAULT_CONFIG;
  return {
    weights: { ...DEFAULT_CONFIG.weights, ...stored.weights },
    levels: { ...DEFAULT_CONFIG.levels, ...stored.levels },
    cacheTtlMinutes: stored.cacheTtlMinutes ?? DEFAULT_CONFIG.cacheTtlMinutes,
    sectorId: stored.sectorId ?? DEFAULT_CONFIG.sectorId,
    anglerName: stored.anglerName ?? "",
    notifications: stored.notifications ?? false,
  };
}

export async function saveConfig(next: AppConfig): Promise<void> {
  const sum =
    next.weights.water +
    next.weights.pressure +
    next.weights.wind +
    next.weights.cloud +
    next.weights.historical;
  if (sum <= 0) throw new Error("Les pondérations doivent être > 0");
  await writeJson("config.json", next);
}

import type { FishingAlert } from "../types";
import { formatTime } from "../format";
import { pressureDeltas, type PressureSeries } from "./pressure";

export function buildAlerts(opts: {
  ifNow: number | null;
  confidence: number;
  window: { from: string; to: string; peak: number } | null;
  pressure: PressureSeries;
  windNow: number | null;
  windPlus6: number | null;
  waterDelta24: number | null;
}): FishingAlert[] {
  const alerts: FishingAlert[] = [];

  if (opts.window && opts.window.peak >= 76) {
    alerts.push({
      id: "fenetre",
      kind: "fenetre",
      title: "Fenêtre favorable détectée",
      body: `${formatTime(opts.window.from)} → ${formatTime(opts.window.to)} · IF prévu ${opts.window.peak} · confiance ${opts.confidence} %`,
    });
  }

  const d = pressureDeltas(opts.pressure);
  if (d.d12 != null && d.d12 <= -4) {
    alerts.push({
      id: "pression",
      kind: "pression",
      title: "Chute de pression",
      body: `${d.d12.toFixed(1)} hPa en 12 h. Le modèle V1 traite une baisse progressive comme un signal, une chute brutale comme un régime instable.`,
    });
  }

  if (opts.windNow != null && opts.windPlus6 != null && Math.abs(opts.windPlus6 - opts.windNow) >= 15) {
    alerts.push({
      id: "vent",
      kind: "vent",
      title: "Changement de vent prévu",
      body: `Passage de ${Math.round(opts.windNow)} à ${Math.round(opts.windPlus6)} km/h d'ici 6 h.`,
    });
  }

  if (opts.waterDelta24 != null && Math.abs(opts.waterDelta24) >= 1.8) {
    alerts.push({
      id: "temperature",
      kind: "temperature",
      title: "Variation thermique de l'eau",
      body: `${opts.waterDelta24 > 0 ? "+" : ""}${opts.waterDelta24.toFixed(1)} °C estimés sur 24 h.`,
    });
  }

  if (opts.ifNow != null && opts.ifNow >= 91) {
    alerts.push({
      id: "exceptionnel",
      kind: "exceptionnel",
      title: "Conditions exceptionnelles (modèle)",
      body: `IF ${opts.ifNow}/100. Ce n'est pas une garantie de capture — uniquement un alignement des facteurs environnementaux V1.`,
    });
  }

  return alerts;
}

import { clamp } from "../format";

export function scoreCloud(opts: {
  cloudPct: number | null;
  hour?: number | null;
  precipMm?: number | null;
}): { score: number; detail: string; available: boolean } {
  if (opts.cloudPct == null) {
    return { score: 0, detail: "Donnée indisponible", available: false };
  }
  const c = opts.cloudPct;
  let score: number;
  if (c >= 60 && c <= 90) score = 92;
  else if (c > 90) score = 80;
  else if (c >= 40) score = 74;
  else if (c >= 20) score = 52;
  else score = 34;

  if (opts.precipMm != null && opts.precipMm > 2) score -= 10;
  if (opts.precipMm != null && opts.precipMm > 6) score -= 10;

  if (opts.hour != null && (opts.hour <= 8 || opts.hour >= 18)) score += 6;

  return {
    score: clamp(Math.round(score), 0, 100),
    detail: `${Math.round(c)} % de nébulosité${opts.precipMm && opts.precipMm > 0.2 ? `, ${opts.precipMm.toFixed(1)} mm` : ""}`,
    available: true,
  };
}

import type { FactorScore } from "../types";
import { pressureTrendLabel } from "./pressure";

export function explainScore(opts: {
  total: number | null;
  factors: FactorScore[];
  waterNote?: string;
  pressureDelta12?: number | null;
  windText?: string;
  analogCount: number;
  catchRate: number | null;
  confidence: number;
}): string[] {
  const lines: string[] = [];
  if (opts.total == null) {
    lines.push("Impossible de calculer l'indice : trop de données manquantes.");
    return lines;
  }

  if (opts.total >= 76) lines.push("Conditions environnementales actuellement favorables selon le modèle V1.");
  else if (opts.total >= 61) lines.push("Conditions globalement correctes, sans régime exceptionnel.");
  else if (opts.total >= 41) lines.push("Conditions mixtes : certains facteurs aident, d'autres limitent.");
  else lines.push("Conditions peu favorables au modèle actuel.");

  const ranked = [...opts.factors].filter((f) => f.available).sort((a, b) => b.rawScore - a.rawScore);
  const best = ranked[0];
  const worst = ranked[ranked.length - 1];
  if (best) lines.push(`Facteur le plus porteur : ${best.label.toLowerCase()} (${best.detail}).`);
  if (worst && worst.id !== best?.id) {
    lines.push(`Facteur le plus limitant : ${worst.label.toLowerCase()} (${worst.detail}).`);
  }

  if (opts.waterNote) lines.push(opts.waterNote);
  if (opts.pressureDelta12 != null) {
    lines.push(`Pression ${pressureTrendLabel(opts.pressureDelta12)} sur 12 h.`);
  }
  if (opts.windText) lines.push(opts.windText);

  lines.push(
    `${opts.analogCount} journée${opts.analogCount > 1 ? "s" : ""} historique${opts.analogCount > 1 ? "s" : ""} à conditions météo comparables.`,
  );

  if (opts.catchRate == null) {
    lines.push(
      "Pas de statistique de capture : le journal local est insuffisant. Il s'agit de similarité météorologique, pas d'une probabilité de prendre un poisson.",
    );
  } else {
    lines.push(
      `Parmi les analogues avec captures enregistrées, ${opts.catchRate} % des journées ont au moins une prise (échantillon encore limité).`,
    );
  }

  if (opts.confidence < 60) {
    lines.push(
      `Confiance ${opts.confidence} % : le score environnemental peut être élevé ou bas, mais la prédiction reste fragile.`,
    );
  }

  return lines;
}

export function bestWindow(hourly: { time: string; ifScore: number | null }[]): {
  from: string;
  to: string;
  peak: number;
} | null {
  const scored = hourly.filter((h): h is { time: string; ifScore: number } => h.ifScore != null);
  if (scored.length < 3) return null;
  let bestStart = 0;
  let bestSum = -1;
  const w = 3;
  for (let i = 0; i <= scored.length - w; i++) {
    const sum = scored[i].ifScore + scored[i + 1].ifScore + scored[i + 2].ifScore;
    if (sum > bestSum) {
      bestSum = sum;
      bestStart = i;
    }
  }
  const slice = scored.slice(bestStart, bestStart + w);
  return {
    from: slice[0].time,
    to: slice[slice.length - 1].time,
    peak: Math.max(...slice.map((s) => s.ifScore)),
  };
}

export interface FishingWindow {
  from: string;
  to: string;
  peak: number;
  peakTime: string;
  startIdx: number;
  endIdx: number;
  peakIdx: number;
}

export function nowHourIndex(hourly: { time: string }[], at = Date.now()): number {
  if (!hourly.length) return 0;
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < hourly.length; i++) {
    const d = Math.abs(new Date(hourly[i].time).getTime() - at);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

/** Pics locaux — pas toute une journée au-dessus de 76. */
export function bestFishingWindows(
  hourly: { time: string; ifScore: number | null }[],
  maxWindows = 3,
): FishingWindow[] {
  const scored = hourly
    .map((h, i) => ({ i, time: h.time, ifScore: h.ifScore }))
    .filter((h): h is { i: number; time: string; ifScore: number } => h.ifScore != null);
  if (scored.length < 3) return [];

  const max = Math.max(...scored.map((s) => s.ifScore));
  const peakLocs: number[] = [];
  for (let k = 1; k < scored.length - 1; k++) {
    const p = scored[k].ifScore;
    if (p >= scored[k - 1].ifScore && p > scored[k + 1].ifScore) peakLocs.push(k);
  }
  if (!peakLocs.length) {
    const hi = scored.reduce((b, s, k) => (s.ifScore > scored[b].ifScore ? k : b), 0);
    peakLocs.push(hi);
  }

  const kept = peakLocs
    .filter((k) => scored[k].ifScore >= max - 4)
    .sort((a, b) => scored[b].ifScore - scored[a].ifScore || a - b)
    .slice(0, maxWindows)
    .sort((a, b) => a - b);

  const windows: FishingWindow[] = [];
  for (const pk of kept) {
    const peakScore = scored[pk].ifScore;
    let L = pk;
    let R = pk;
    while (
      L > 0 &&
      scored[L - 1].ifScore >= peakScore - 4 &&
      scored[L - 1].ifScore >= 61 &&
      pk - (L - 1) < 3
    ) {
      L -= 1;
    }
    while (
      R < scored.length - 1 &&
      scored[R + 1].ifScore >= peakScore - 4 &&
      scored[R + 1].ifScore >= 61 &&
      R + 1 - pk < 3
    ) {
      R += 1;
    }
    if (windows.some((w) => !(scored[R].i < w.startIdx || scored[L].i > w.endIdx))) continue;
    windows.push({
      from: scored[L].time,
      to: scored[R].time,
      peak: peakScore,
      peakTime: scored[pk].time,
      startIdx: scored[L].i,
      endIdx: scored[R].i,
      peakIdx: scored[pk].i,
    });
  }
  return windows.sort((a, b) => a.startIdx - b.startIdx);
}

import type {
  FactorScore,
  FrenzyLevel,
  LevelThresholds,
  ModelWeights,
  SpeciesId,
} from "../types";
