import type { AnalogDay, CatchRecord } from "../types";

export interface DailyClimate {
  date: string;
  airTempC: number | null;
  pressureHpa: number | null;
  pressureDelta: number | null;
  windKmh: number | null;
  windDirDeg: number | null;
  cloudPct: number | null;
}

function n(v: number | null, min: number, max: number): number | null {
  if (v == null || Number.isNaN(v)) return null;
  return (v - min) / (max - min);
}

function circ(deg: number | null): { s: number; c: number } | null {
  if (deg == null) return null;
  const r = (deg * Math.PI) / 180;
  return { s: Math.sin(r), c: Math.cos(r) };
}

function doy(date: string): number {
  const d = new Date(date + "T12:00:00Z");
  const start = Date.UTC(d.getUTCFullYear(), 0, 0);
  return (d.getTime() - start) / 86400000;
}

export function analogDistance(a: DailyClimate, b: DailyClimate): number {
  const parts: number[] = [];
  const push = (x: number | null, y: number | null, w: number) => {
    if (x == null || y == null) return;
    parts.push(w * (x - y) ** 2);
  };
  push(n(a.airTempC, -5, 40), n(b.airTempC, -5, 40), 1.2);
  push(n(a.pressureHpa, 980, 1040), n(b.pressureHpa, 980, 1040), 1);
  push(n(a.pressureDelta, -15, 15), n(b.pressureDelta, -15, 15), 1.1);
  push(n(a.windKmh, 0, 50), n(b.windKmh, 0, 50), 0.9);
  push(n(a.cloudPct, 0, 100), n(b.cloudPct, 0, 100), 0.8);
  const wa = circ(a.windDirDeg);
  const wb = circ(b.windDirDeg);
  if (wa && wb) {
    parts.push(0.5 * ((wa.s - wb.s) ** 2 + (wa.c - wb.c) ** 2));
  }
  const da = doy(a.date);
  const db = doy(b.date);
  const angA = (da / 365) * Math.PI * 2;
  const angB = (db / 365) * Math.PI * 2;
  parts.push(0.7 * ((Math.sin(angA) - Math.sin(angB)) ** 2 + (Math.cos(angA) - Math.cos(angB)) ** 2));
  if (!parts.length) return 1;
  return Math.sqrt(parts.reduce((s, x) => s + x, 0) / parts.length);
}

export function findAnalogs(
  current: DailyClimate,
  archive: DailyClimate[],
  catches: CatchRecord[],
  limit = 12,
  threshold = 0.28,
): { analogs: AnalogDay[]; similarCount: number; meanDistance: number | null } {
  const scored = archive
    .filter((d) => d.date !== current.date)
    .map((d) => ({ d, dist: analogDistance(current, d) }))
    .sort((a, b) => a.dist - b.dist);

  const similar = scored.filter((x) => x.dist <= threshold);
  const top = (similar.length ? similar : scored.slice(0, 5)).slice(0, limit);

  const analogs: AnalogDay[] = top.map(({ d, dist }) => ({
    date: d.date,
    distance: Number(dist.toFixed(3)),
    airTempC: d.airTempC,
    pressureHpa: d.pressureHpa,
    windKmh: d.windKmh,
    cloudPct: d.cloudPct,
    catchesThatDay: catches.filter((c) => c.date === d.date).length,
  }));

  const meanDistance =
    similar.length > 0
      ? similar.slice(0, 20).reduce((s, x) => s + x.dist, 0) / Math.min(20, similar.length)
      : null;

  return { analogs, similarCount: similar.length, meanDistance };
}

export function historicalFactor(opts: {
  similarCount: number;
  meanDistance: number | null;
  archiveDays: number;
}): { score: number | null; detail: string } {
  if (opts.archiveDays < 14) {
    return { score: null, detail: "Historique insuffisant pour le matching." };
  }
  if (opts.similarCount === 0 || opts.meanDistance == null) {
    return {
      score: 42,
      detail: "Peu d'analogues météo proches — situation atypique pour le secteur.",
    };
  }
  const closeness = 1 - Math.min(1, opts.meanDistance / 0.28);
  const volume = Math.min(1, opts.similarCount / 25);
  const score = Math.round(45 + 40 * closeness + 15 * volume);
  return {
    score,
    detail: `${opts.similarCount} journées météo similaires (distance moyenne ${opts.meanDistance.toFixed(2)}). Similarité météorologique uniquement.`,
  };
}

export function catchRateOnAnalogs(analogs: AnalogDay[]): {
  daysWithCatches: number;
  rate: number | null;
} {
  const withData = analogs.filter((a) => a.catchesThatDay > 0);
  if (withData.length < 5) return { daysWithCatches: withData.length, rate: null };
  return {
    daysWithCatches: withData.length,
    rate: Math.round((withData.length / analogs.length) * 100),
  };
}

import type { FishingPlanSlot, SpeciesId } from "../types";
import { SPECIES_MODIFIERS } from "./fishing";
import { clamp } from "../format";

export function buildPlan(opts: {
  startIso: string;
  durationHours: number;
  species: SpeciesId | "tous";
  hourly: { time: string; ifScore: number | null; water: number | null; cloud: number | null; wind: number | null }[];
}): FishingPlanSlot[] {
  const start = new Date(opts.startIso).getTime();
  const end = start + opts.durationHours * 3600_000;
  const window = opts.hourly.filter((h) => {
    const t = new Date(h.time).getTime();
    return t >= start - 20 * 60_000 && t <= end + 20 * 60_000;
  });
  if (!window.length) return [];

  const adjusted = window.map((h) => {
    let s = h.ifScore;
    if (s != null && opts.species !== "tous") {
      const hour = new Date(h.time).getHours();
      s = clamp(
        s +
          SPECIES_MODIFIERS[opts.species].shift({
            water: h.water,
            cloud: h.cloud,
            hour,
            wind: h.wind,
          }),
        0,
        100,
      );
    }
    return { ...h, ifScore: s };
  });

  const slots: FishingPlanSlot[] = [];
  const step = Math.max(2, Math.round(adjusted.length / 3));
  for (let i = 0; i < adjusted.length; i += step) {
    const chunk = adjusted.slice(i, i + step).filter((x) => x.ifScore != null);
    if (!chunk.length) continue;
    const avg = Math.round(chunk.reduce((a, x) => a + (x.ifScore ?? 0), 0) / chunk.length);
    slots.push({
      from: chunk[0].time,
      to: chunk[chunk.length - 1].time,
      ifScore: avg,
      label: avg >= 76 ? "Meilleure fenêtre" : avg >= 61 ? "Conditions favorables" : avg >= 41 ? "Correct" : "Peu favorable",
      best: false,
    });
  }
  if (!slots.length) return slots;
  const max = Math.max(...slots.map((s) => s.ifScore));
  return slots.map((s) => ({ ...s, best: s.ifScore === max && max >= 61 }));
}

import { clamp } from "../format";

export interface PressureSeries {
  current: number | null;
  h3: number | null;
  h6: number | null;
  h12: number | null;
  h24: number | null;
}

export function pressureDeltas(s: PressureSeries) {
  const d = (a: number | null, b: number | null) =>
    a != null && b != null ? Number((a - b).toFixed(2)) : null;
  return {
    d3: d(s.current, s.h3),
    d6: d(s.current, s.h6),
    d12: d(s.current, s.h12),
    d24: d(s.current, s.h24),
  };
}

export function pressureTrendLabel(d12: number | null): string {
  if (d12 === null) return "tendance inconnue";
  if (d12 <= -4) return "chute marquée";
  if (d12 <= -1) return "en baisse";
  if (d12 < 1) return "stable";
  if (d12 < 4) return "en hausse";
  return "hausse marquée";
}

/**
 * Privilégie les variations, pas une valeur isolée.
 * Une baisse progressive 1–4 hPa / 12 h est le régime le plus favorable du modèle V1.
 */
export function scorePressure(s: PressureSeries): {
  score: number;
  detail: string;
  available: boolean;
} {
  if (s.current == null) {
    return { score: 0, detail: "Donnée indisponible", available: false };
  }

  const { d12, d24 } = pressureDeltas(s);
  const delta = d12 ?? d24;
  if (delta == null) {
    const abs = s.current;
    const absScore = abs >= 1005 && abs <= 1022 ? 62 : abs < 995 || abs > 1035 ? 40 : 52;
    return {
      score: absScore,
      detail: `${abs.toFixed(0)} hPa — variation indisponible, score sur valeur seule (confiance réduite)`,
      available: true,
    };
  }

  let trendScore: number;
  if (delta <= -6) trendScore = 48;
  else if (delta <= -4) trendScore = 70;
  else if (delta <= -1) trendScore = 92;
  else if (delta < 1) trendScore = 64;
  else if (delta < 3) trendScore = 58;
  else if (delta < 6) trendScore = 46;
  else trendScore = 38;

  let absAdj = 0;
  if (s.current < 995 || s.current > 1038) absAdj = -12;
  else if (s.current >= 1004 && s.current <= 1020) absAdj = 4;

  const speed = d12 != null && s.h3 != null && s.current != null
    ? Math.abs(s.current - s.h3) * 4
    : 0;
  const shock = speed > 6 ? -10 : 0;

  const score = clamp(Math.round(trendScore + absAdj + shock), 0, 100);
  const sign = delta > 0 ? "+" : "";
  return {
    score,
    detail: `${s.current.toFixed(0)} hPa, ${sign}${delta.toFixed(1)} hPa / 12h (${pressureTrendLabel(d12)})`,
    available: true,
  };
}

import type { CatchRecord, SpeciesId } from "../types";
import { SPECIES_MODIFIERS } from "./fishing";

function avg(xs: number[]): number | null {
  if (!xs.length) return null;
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

export function analyzeCatches(catches: CatchRecord[]) {
  const byHour = Array.from({ length: 24 }, () => 0);
  const bySpecies: Record<string, number> = {};
  for (const c of catches) {
    const h = Number(String(c.time).slice(0, 2));
    if (!Number.isNaN(h) && h >= 0 && h < 24) byHour[h] += 1;
    bySpecies[c.species] = (bySpecies[c.species] ?? 0) + 1;
  }
  const ifs = catches
    .map((c) => c.weatherSnapshot.ifScore)
    .filter((v): v is number => v != null);
  const waters = catches
    .map((c) => c.weatherSnapshot.waterTempC)
    .filter((v): v is number => v != null);
  const bestHours = byHour
    .map((n, h) => ({ h, n }))
    .filter((x) => x.n > 0)
    .sort((a, b) => b.n - a.n)
    .slice(0, 3);

  return {
    n: catches.length,
    ready: catches.length >= 5,
    byHour,
    bySpecies,
    meanIfAtCatch: avg(ifs),
    meanWaterAtCatch: avg(waters),
    bestHours,
    alignment:
      ifs.length >= 8
        ? {
            ready: true as const,
            meanIf: Number(avg(ifs)!.toFixed(1)),
            note:
              avg(ifs)! >= 60
                ? "Les prises enregistrées arrivent surtout par IF élevé : le modèle V1 n'est pas contredit par votre journal."
                : "Des prises arrivent à IF modéré : le modèle V1 n'est pas encore spécifique à vos sessions.",
          }
        : {
            ready: false as const,
            meanIf: avg(ifs),
            note: "Il faut au moins 8 captures avec IF collé pour juger l'alignement du modèle.",
          },
  };
}

export function empiricalSpeciesShift(
  catches: CatchRecord[],
  species: SpeciesId,
  hour: number | null,
): { shift: number; calibrated: boolean; n: number } {
  const xs = catches.filter((c) => c.species === species);
  if (xs.length < 8) return { shift: 0, calibrated: false, n: xs.length };
  const hours = xs
    .map((c) => Number(String(c.time).slice(0, 2)))
    .filter((h) => !Number.isNaN(h));
  const meanH = avg(hours);
  if (meanH == null || hour == null) return { shift: 2, calibrated: true, n: xs.length };
  const dist = Math.abs(((hour - meanH + 12) % 24) - 12);
  const shift = dist <= 2 ? 6 : dist <= 4 ? 3 : -2;
  return { shift, calibrated: true, n: xs.length };
}

export function speciesWithLocalStats(
  base: ReturnType<typeof import("./fishing").speciesScores>,
  catches: CatchRecord[],
  hour: number | null,
) {
  return base.map((s) => {
    const emp = empiricalSpeciesShift(catches, s.id, hour);
    if (!emp.calibrated || s.score == null) {
      return { ...s, calibrated: false as const, n: emp.n };
    }
    const score = Math.max(0, Math.min(100, s.score + emp.shift));
    return {
      ...s,
      score,
      calibrated: true as const,
      n: emp.n,
      note: `Calibré sur ${emp.n} captures locales ${SPECIES_MODIFIERS[s.id].label.toLowerCase()} + heuristique V1.`,
    };
  });
}

import { WATER_CLIMATOLOGY_C } from "../lake";
import { clamp, lerp } from "../format";
import type { DataKind, WaterMeasure } from "../types";

export function climatologyAt(date: Date): number {
  const month = date.getUTCMonth();
  const next = (month + 1) % 12;
  const day = date.getUTCDate();
  const dim = new Date(Date.UTC(date.getUTCFullYear(), month + 1, 0)).getUTCDate();
  const t = (day - 1) / Math.max(1, dim - 1);
  return lerp(WATER_CLIMATOLOGY_C[month], WATER_CLIMATOLOGY_C[next], t);
}

/**
 * Modèle de lag thermique : l'eau suit l'air avec inertie, autour de la normale saisonnière.
 * Toujours étiqueté ESTIMATION — jamais présenté comme une mesure de station.
 */
export function estimateWaterTempC(opts: {
  at: Date;
  airMean5d: number | null;
  airNow: number | null;
}): { value: number; kind: DataKind; confidence: "moyenne" | "faible"; note: string } {
  const clima = climatologyAt(opts.at);
  if (opts.airMean5d == null && opts.airNow == null) {
    return {
      value: Number(clima.toFixed(1)),
      kind: "estimation",
      confidence: "faible",
      note: "Climatologie saisonnière uniquement — pas de série d'air disponible.",
    };
  }
  const air = opts.airMean5d ?? opts.airNow ?? clima;
  const pulled = clima + 0.42 * (air - clima);
  const hour = opts.at.getHours();
  const diurnal = 0.35 * Math.sin(((hour - 15) / 24) * Math.PI * 2);
  return {
    value: Number((pulled + diurnal).toFixed(1)),
    kind: "estimation",
    confidence: opts.airMean5d != null ? "moyenne" : "faible",
    note: "Température de surface estimée (climatologie Sanguinet + inertie thermique). Ce n'est pas une mesure in situ.",
  };
}

export function waterAnomaly(value: number, at: Date): number {
  return Number((value - climatologyAt(at)).toFixed(1));
}

export function applyWaterMeasure(
  estimated: { value: number; kind: DataKind; confidence: "moyenne" | "faible"; note: string },
  measure: WaterMeasure | null,
): {
  value: number;
  kind: DataKind;
  confidence: "moyenne" | "faible" | "haute";
  note: string;
  measured: boolean;
} {
  if (!measure) return { ...estimated, measured: false };
  const ageH = (Date.now() - new Date(measure.at).getTime()) / 3_600_000;
  if (ageH < 0 || Number.isNaN(ageH)) return { ...estimated, measured: false };
  if (ageH <= 12) {
    return {
      value: measure.tempC,
      kind: "mesure",
      confidence: "haute",
      note: `Mesure in situ (${measure.source}) — ${ageH < 1 ? "moins d'1 h" : `${ageH.toFixed(0)} h`}.`,
      measured: true,
    };
  }
  if (ageH <= 36) {
    const t = 1 - (ageH - 12) / 24;
    return {
      value: Number((t * measure.tempC + (1 - t) * estimated.value).toFixed(1)),
      kind: "estimation",
      confidence: "moyenne",
      note: `Estimation corrigée par une mesure de ${ageH.toFixed(0)} h — ce n'est plus une mesure actuelle.`,
      measured: false,
    };
  }
  return { ...estimated, measured: false };
}

/**
 * Plage V1 carnassiers d'eau douce tempérée : 11–18 °C optimal.
 * Les tendances lentes valent mieux qu'un choc thermique.
 */
export function scoreWater(opts: {
  tempC: number | null;
  delta6h?: number | null;
  delta24h?: number | null;
}): { score: number; detail: string; available: boolean } {
  if (opts.tempC == null) {
    return { score: 0, detail: "Donnée indisponible", available: false };
  }
  const t = opts.tempC;
  let score: number;
  if (t >= 11 && t <= 18) score = 94 - Math.abs(t - 14.5) * 1.2;
  else if (t >= 8 && t < 11) score = 70 + (t - 8) * 7;
  else if (t > 18 && t <= 22) score = 88 - (t - 18) * 6;
  else if (t >= 6 && t < 8) score = 48 + (t - 6) * 10;
  else if (t > 22 && t <= 25) score = 58 - (t - 22) * 6;
  else if (t < 6) score = clamp(18 + t * 3, 5, 40);
  else score = clamp(40 - (t - 25) * 5, 8, 40);

  const d24 = opts.delta24h;
  if (d24 != null) {
    if (Math.abs(d24) < 0.4) score += 4;
    else if (Math.abs(d24) > 2.5) score -= 8;
  }

  return {
    score: clamp(Math.round(score), 0, 100),
    detail: `${t.toFixed(1)} °C surface — ${t >= 11 && t <= 18 ? "plage favorable au modèle V1" : "hors plage optimale V1"}`,
    available: true,
  };
}

import { clamp } from "../format";
import type { Cardinal } from "../types";

export function toCardinal(deg: number): Cardinal {
  const dirs: Cardinal[] = ["N", "NE", "E", "SE", "S", "SO", "O", "NO"];
  return dirs[Math.round((((deg % 360) + 360) % 360) / 45) % 8];
}

export function windVector(speedKmh: number, dirDeg: number): { u: number; v: number } {
  const rad = ((dirDeg + 180) * Math.PI) / 180;
  return {
    u: speedKmh * Math.sin(rad),
    v: speedKmh * Math.cos(rad),
  };
}

/**
 * Vent traité comme vecteur. Le score privilégie un vent modéré
 * (agitation, oxygénation) plutôt que le calme plat ou la tempête.
 * Ce n'est pas une vérité scientifique définitive — modèle V1.
 */
export function scoreWind(opts: {
  speedKmh: number | null;
  gustKmh?: number | null;
}): { score: number; detail: string; available: boolean } {
  if (opts.speedKmh === null || opts.speedKmh === undefined) {
    return { score: 0, detail: "Donnée indisponible", available: false };
  }
  const s = opts.speedKmh;
  let score: number;
  let band: string;
  if (s < 3) {
    score = 22;
    band = "calme plat";
  } else if (s < 8) {
    score = 58 + (s - 3) * 4;
    band = "faible";
  } else if (s <= 22) {
    score = 86 + (1 - Math.abs(s - 14) / 14) * 12;
    band = "modéré";
  } else if (s <= 32) {
    score = 72 - (s - 22) * 1.6;
    band = "soutenu";
  } else if (s <= 45) {
    score = 48 - (s - 32);
    band = "fort";
  } else {
    score = 12;
    band = "tempête";
  }

  if (opts.gustKmh != null && opts.speedKmh > 0 && opts.gustKmh > opts.speedKmh * 1.7) {
    score -= 8;
    band += ", rafales irrégulières";
  }

  return {
    score: clamp(Math.round(score), 0, 100),
    detail: `${Math.round(s)} km/h — régime ${band}`,
    available: true,
  };
}

export function downwindBearing(fromDeg: number): number {
  return (fromDeg + 180) % 360;
}

function bearing(from: [number, number], to: [number, number]): number {
  const dLon = ((to[0] - from[0]) * Math.PI) / 180;
  const lat1 = (from[1] * Math.PI) / 180;
  const lat2 = (to[1] * Math.PI) / 180;
  const y = Math.sin(dLon) * Math.cos(lat2);
  const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLon);
  return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360;
}

function angDiff(a: number, b: number): number {
  return Math.abs(((a - b + 540) % 360) - 180);
}

/** Rive sous le vent (côte battue), sans bathymétrie. */
export function exposedShore(
  polygon: [number, number][],
  windFromDeg: number,
): [number, number][] {
  const down = downwindBearing(windFromDeg);
  const cx = polygon.reduce((s, p) => s + p[0], 0) / polygon.length;
  const cy = polygon.reduce((s, p) => s + p[1], 0) / polygon.length;
  return polygon.filter((p) => angDiff(bearing([cx, cy], p), down) <= 55);
}

